import React from 'react';
import { Link } from 'gatsby';
import { Content, Header, Layout, SEO, SectionTitle, Title, Wrapper } from '../components';
import config from '../../config/SiteConfig';

interface Props {
  pageContext: { classifications: Array<{ name: string; count: number }> };
}

export default function AllCategoryTemplate({ pageContext }: Props) {
  return (
    <Layout>
      <Header>
        <Link to="/">
          <strong>{config.siteTitle}</strong>
        </Link>
        <SectionTitle>Categories</SectionTitle>
      </Header>
      <Wrapper>
        <Content>
          {pageContext.classifications.map(({ name, count }) => (
            <Title key={name}>
              <Link to={`/categories/${name}/`}>
                {name} ({count})
              </Link>
            </Title>
          ))}
        </Content>
      </Wrapper>
    </Layout>
  );
}

export const Head = () => (
  <SEO
    pathname="/categories/"
    title={`카테고리 | ${config.siteTitle}`}
    description="기술 원리, 활용 방법, 오류 해결과 회고 글을 주제별 카테고리로 모았습니다."
  />
);
